(function() {
  const postsContainer = document.getElementById('posts-container-load-more');
  const loadMoreButton = document.getElementById('load-more-button');
  const loadMoreSpinner = document.getElementById('load-more-spinner');
  const noMorePostsMessage = document.getElementById('no-more-posts');

  // IMPORTANT: Substitua pelo URL real do seu blog (ex: 'https://meublog.blogspot.com')
  const blogUrl = 'https://YOUR_BLOG_NAME.blogspot.com';
  const postsPerPage = 5; // Número de posts a carregar por requisição
  let nextPostUrl = ''; // URL para o próximo conjunto de posts

  // Função para criar o HTML de um card de post
  function createPostCard(post) {
    const postUrl = post.link.find(l => l.rel === 'alternate').href;
    const postTitle = post.title.$t;
    const postSummary = post.summary.$t.length > 150 ? post.summary.$t.substring(0, 150) + '...' : post.summary.$t;
    const postImage = post.media$thumbnail ? post.media$thumbnail.url.replace('/s72-c/', '/w400/') : 'https://via.placeholder.com/400x250/cccccc/ffffff?text=No+Image';

    return `
      <div class="col">
        <div class="card h-100 shadow-sm" style="background-color: var(--sl-card-bg); border-color: var(--sl-border);">
          <img src="${postImage}" class="card-img-top" alt="${postTitle}" style="object-fit: cover; height: 180px;">
          <div class="card-body">
            <h5 class="card-title" style="color: var(--sl-text-main);">${postTitle}</h5>
            <p class="card-text" style="color: var(--sl-text-main);">${postSummary}</p>
            <a href="${postUrl}" class="btn btn-sm" style="background-color: var(--sl-primary); color: var(--sl-bg-body);">Ler Mais</a>
          </div>
        </div>
      </div>
    `;
  }

  // Função para buscar e exibir posts
  async function fetchPosts() {
    loadMoreButton.classList.add('d-none');
    loadMoreSpinner.classList.remove('d-none');

    try {
      // Para a primeira carga, usa start-index. Para as subsequentes, usa nextPostUrl.
      // O Blogger JSON feed precisa de 'alt=json' para ser parseado diretamente por fetch.
      const feedUrl = nextPostUrl || `${blogUrl}/feeds/posts/summary?alt=json&start-index=1&max-results=${postsPerPage}`;

      const response = await fetch(feedUrl);
      const data = await response.json();

      const posts = data.feed.entry || [];
      const fragment = document.createDocumentFragment();

      if (posts.length === 0) {
        noMorePostsMessage.classList.remove('d-none');
        loadMoreButton.classList.add('d-none');
        return;
      }

      posts.forEach(post => {
        const div = document.createElement('div');
        div.innerHTML = createPostCard(post);
        fragment.appendChild(div.firstElementChild);
      });
      postsContainer.appendChild(fragment);

      // Atualiza nextPostUrl para a próxima busca
      const nextLink = data.feed.link.find(l => l.rel === 'next');
      if (nextLink) {
        nextPostUrl = nextLink.href;
        loadMoreButton.classList.remove('d-none');
      } else {
        noMorePostsMessage.classList.remove('d-none');
        loadMoreButton.classList.add('d-none');
      }

    } catch (error) {
      console.error('Erro ao carregar posts:', error);
      loadMoreButton.classList.remove('d-none'); // Reabilita o botão em caso de erro
    } finally {
      loadMoreSpinner.classList.add('d-none');
    }
  }

  if (loadMoreButton) {
    loadMoreButton.addEventListener('click', fetchPosts);
  }
})();

